import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import MainDashboard from './pages/MainDashboard';
import Shop from './pages/Shop';
import InventoryManager from './pages/InventoryManager';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Orders from './pages/Orders';
import Suppliers from './pages/Suppliers';
import PurchaseOrders from './pages/PurchaseOrders';
import Navigation from './components/Navigation';

function App() {
    return (
        <Router>
            <Routes>
                <Route path="/" element={<MainDashboard />} />
                <Route path="/shop" element={<><Navigation /><Shop /></>} />
                <Route path="/inventory-manager" element={<><Navigation /><InventoryManager /></>} />
                <Route path="/purchase-orders" element={<><Navigation /><PurchaseOrders /></>} />
                <Route path="/dashboard" element={<><Navigation /><Dashboard /></>} />
                <Route path="/inventory" element={<><Navigation /><Inventory /></>} />
                <Route path="/orders" element={<><Navigation /><Orders /></>} />
                <Route path="/suppliers" element={<><Navigation /><Suppliers /></>} />
            </Routes>
        </Router>
    );
}

export default App;
